using System;using System.Linq;using System.Web.Mvc;using System.Web.Security;using _25dh110973_LTW.Models;using _25dh110973_LTW.Models.ViewModel;
namespace _25dh110973_LTW.Controllers { public class AccountController:Controller {MyStoreEntities1 db=new MyStoreEntities1();
 public ActionResult Register(){return View();}
 [HttpPost,ValidateAntiForgeryToken] public ActionResult Register(RegisterVM m){if(!ModelState.IsValid)return View(m);if(db.Users.Any(x=>x.Username==m.Username)){ModelState.AddModelError("Username","Tên đăng nhập đã tồn tại");return View(m);}
 using(var tx=db.Database.BeginTransaction()){try{db.Users.Add(new User{Username=m.Username,Password=Hash(m.Password),UserRole="Customer"});db.Customers.Add(new Customer{Username=m.Username,CustomerName=m.CustomerName,CustomerPhone=m.CustomerPhone,CustomerEmail=m.CustomerEmail,CustomerAddress=m.CustomerAddress});db.SaveChanges();tx.Commit();}catch{tx.Rollback();ModelState.AddModelError("","Không thể tạo tài khoản. Kiểm tra cơ sở dữ liệu.");return View(m);}}FormsAuthentication.SetAuthCookie(m.Username,false);Session["Username"]=m.Username;return RedirectToAction("Index","Home");}
 static string Hash(string password){return "PBKDF2$"+System.Web.Helpers.Crypto.HashPassword(password);}
 static bool Verify(string password,string stored){return stored!=null&&stored.StartsWith("PBKDF2$")&&System.Web.Helpers.Crypto.VerifyHashedPassword(stored.Substring(7),password);}
 public ActionResult Login(string returnUrl){ViewBag.ReturnUrl=returnUrl;return View();}
 [HttpPost,ValidateAntiForgeryToken] public ActionResult Login(LoginVM m,string returnUrl){if(ModelState.IsValid){var u=db.Users.FirstOrDefault(x=>x.Username==m.Username&&x.UserRole=="Customer");if(u!=null&&(Verify(m.Password,u.Password)||(!u.Password.StartsWith("PBKDF2$")&&u.Password==m.Password))){FormsAuthentication.SetAuthCookie(u.Username,false);Session["Username"]=u.Username;if(Url.IsLocalUrl(returnUrl))return Redirect(returnUrl);return RedirectToAction("Index","Home");}ModelState.AddModelError("","Sai tên đăng nhập hoặc mật khẩu");}return View(m);}
 [HttpPost,ValidateAntiForgeryToken] public ActionResult Logout(){FormsAuthentication.SignOut();Session.Clear();return RedirectToAction("Index","Home");}
 [Authorize] public ActionResult ProfileInfo(){var c=db.Customers.FirstOrDefault(x=>x.Username==User.Identity.Name);if(c==null)return HttpNotFound();return View(new ProfileVM{Username=c.Username,CustomerName=c.CustomerName,CustomerPhone=c.CustomerPhone,CustomerEmail=c.CustomerEmail,CustomerAddress=c.CustomerAddress});}
 [HttpPost,Authorize,ValidateAntiForgeryToken] public ActionResult ProfileInfo(ProfileVM m){if(!ModelState.IsValid)return View(m);var c=db.Customers.FirstOrDefault(x=>x.Username==User.Identity.Name);if(c==null)return HttpNotFound();c.CustomerName=m.CustomerName;c.CustomerPhone=m.CustomerPhone;c.CustomerEmail=m.CustomerEmail;c.CustomerAddress=m.CustomerAddress;db.SaveChanges();TempData["Message"]="Đã cập nhật thông tin";return RedirectToAction("ProfileInfo");}
 [Authorize]public ActionResult ChangePassword(){return View();}
 [HttpPost,Authorize,ValidateAntiForgeryToken]public ActionResult ChangePassword(ChangePasswordVM m){if(!ModelState.IsValid)return View(m);var u=db.Users.FirstOrDefault(x=>x.Username==User.Identity.Name&&x.UserRole=="Customer");if(u==null)return HttpNotFound();if(!Verify(m.OldPassword,u.Password)&&u.Password!=m.OldPassword){ModelState.AddModelError("OldPassword","Mật khẩu cũ không đúng");return View(m);}u.Password=Hash(m.NewPassword);db.SaveChanges();TempData["Message"]="Đổi mật khẩu thành công";return RedirectToAction("ProfileInfo");}
 } }